import { getTranslations } from 'next-intl/server';
import { BadgeCheck, ShieldCheck, Smartphone } from 'lucide-react';
import type { HundiQrInfo } from '@/lib/types';

/**
 * Direct UPI donation card - the temple's own QR (generated by the backend from
 * the UPI ID set in Admin -> Temple Info) and the same payment link as a button.
 * Phones get the button first: one tap opens the devotee's UPI app with the
 * temple filled in (a phone can't scan its own screen). Desktops can't open
 * upi:// links, so they get a large QR to scan with a phone instead.
 * Render only when `qr.configured`.
 */
export default async function DonateUpi({ qr, showHeading = true }: { qr: HundiQrInfo; showHeading?: boolean }) {
  const t = await getTranslations('donate');
  return (
    <div id="donate" className="scroll-mt-24 rounded-2xl border border-amber-200 bg-white p-6 text-center shadow-sm sm:p-8">
      {showHeading && (
        <h2 id="donate-heading" className="font-serif text-2xl font-bold text-maroon">{t('title')}</h2>
      )}
      <div className={`flex flex-col items-center gap-5 ${showHeading ? 'mt-5' : ''}`}>
        {qr.upi_uri && (
          <a
            href={qr.upi_uri}
            className="inline-flex w-full max-w-xs items-center justify-center gap-2 rounded-full bg-saffron-dark px-6 py-3.5 text-lg font-bold text-white shadow transition hover:bg-saffron-light hover:text-maroon-dark md:hidden"
          >
            <Smartphone className="h-5 w-5" aria-hidden="true" /> {t('payNow')}
          </a>
        )}
        <figure>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={`data:image/png;base64,${qr.qr_base64}`}
            alt={t('qrAlt')}
            className="mx-auto h-40 w-40 rounded-xl border border-amber-100 md:h-64 md:w-64"
          />
          <figcaption className="mt-2 text-sm text-gray-600">
            <span className="md:hidden">{t('orScan')}</span>
            <span className="hidden md:inline">{t('scanDesktop')}</span>
          </figcaption>
        </figure>
        <dl className="space-y-2 text-sm">
          <div>
            <dt className="text-gray-600">{t('upiId')}</dt>
            <dd className="select-all break-words font-mono text-base font-semibold text-maroon">
              {/* Wrap a long UPI ID after the @ rather than mid-word on narrow phones. */}
              {qr.upi_vpa?.split('@').map((part, i) => (i ? <span key={i}>@<wbr />{part}</span> : part))}
            </dd>
          </div>
          <div>
            <dt className="text-gray-600">{t('accountName')}</dt>
            <dd className="font-semibold text-gray-800">{qr.payee_name}</dd>
          </div>
        </dl>
        <p className="text-xs text-gray-600">{t('apps')}</p>

        {qr.payee_name && (
          <div className="w-full max-w-md rounded-xl border border-green-200 bg-green-50 p-3 text-left text-sm text-green-900">
            <p className="flex items-center gap-1.5 font-semibold">
              <ShieldCheck className="h-4 w-4 shrink-0" aria-hidden="true" /> {t('verifyTitle')}
            </p>
            <p className="mt-1">{t.rich('verifyName', { name: qr.payee_name, b: (chunks) => <strong>{chunks}</strong> })}</p>
            <p className="mt-1 text-green-800">{t('neverAsk')}</p>
          </div>
        )}

        {(qr.registration_number || qr.pan_number || qr.eighty_g_number) && (
          <div className="w-full max-w-md rounded-xl border border-amber-200 bg-amber-50/60 p-3 text-left text-sm">
            <p className="flex items-center gap-1.5 font-semibold text-maroon">
              <BadgeCheck className="h-4 w-4 shrink-0" aria-hidden="true" /> {t('officialDetails')}
            </p>
            <dl className="mt-2 grid grid-cols-[auto_1fr] gap-x-3 gap-y-1">
              {qr.registration_number && (<><dt className="text-gray-600">{t('regNo')}</dt><dd className="font-mono font-medium text-gray-800">{qr.registration_number}</dd></>)}
              {qr.pan_number && (<><dt className="text-gray-600">{t('pan')}</dt><dd className="font-mono font-medium text-gray-800">{qr.pan_number}</dd></>)}
              {qr.eighty_g_number && (<><dt className="text-gray-600">{t('eightyG')}</dt><dd className="break-all font-mono font-medium text-gray-800">{qr.eighty_g_number}</dd></>)}
            </dl>
            {qr.eighty_g_number && <p className="mt-2 text-xs text-gray-600">{t('eightyGNote')}</p>}
          </div>
        )}
      </div>
    </div>
  );
}
